/bin/bash -lc "python - <<'PY'
qs={'READ_133','READ_15094','READ_24513','READ_25707','READ_37145','READ_42026','READ_94187','READ_146','READ_958','READ_37271','READ_62647','READ_92031','READ_92262','READ_109308'}
t2g={}
for line in open('refs/ensembl_t2g.tsv'):
    tid,g=line.rstrip('\\n').split('\\t')[:2]; t2g[tid]=g
for line in open('work/primary_cdna.sam'):
    if line.startswith('@'): continue
    f=line.rstrip('\\n').split('\\t')
    if f[0] in qs:
        flag=int(f[1]); r='R1' if flag&64 else 'R2' if flag&128 else '?'
        strand='-' if flag&16 else '+'
        print(f[0],r,flag,strand,t2g.get(f[2],f[2]),f[2],f[3],f[4],f[5],f[6],f[7],f[8],sep='\\t')
PY"
